import csv
from pathlib import Path
p=Path(__file__).resolve().parent;f=p/'store_facts.csv'
prod='https://tryskult.com/products/sculpting-face-wrap?currency=USD';policy='https://tryskult.com/pages/subscription-policy'
with f.open(encoding='utf-8-sig',newline='') as stream:
 r=csv.DictReader(stream);fields=r.fieldnames;rows=list(r)
row=dict(category='chin_wrap',domain='tryskult.com',sells='yes',product_url=prod,price_one_bar='unknown: standalone single-wrap price not offered on initial page; two-wrap initial bundle $34.99; one-time checkout cart displayed 2 for $44.99',bundles='two wraps $34.99; four $49.99; six $64.99 on initial product view; one-time two-wrap cart $44.99',default_bundle='two wraps $34.99; first bundle radio checked',subscription='page initially displayed refills every four weeks and link One Time Purchase; recurring sale selection inferred but initial checkout terms not confirmed; one-time link automatically added two wraps at $44.99',refill_interval='every 4 weeks on product page; policy says frequency chosen at checkout',subscription_cancellation='policy says 2 paid billing cycles minimum, then cancel via account dashboard or email; page says Stop or Cancel Anytime, potentially confusing',shipping='product page says free above $40, US and Canada 5–10 business days via USPS; fee below threshold unknown',ships_from='unknown',returns='product FAQ says 30-day money-back guarantee; subscription policy states first subscription order guarantee has 60-day usage requirement and 90-day claim limit; exceptions and applicability differ',review_widget='unknown',review_count='149 and 4.7/5 in product header; a separate page section says 50,000+; seller figures not independently verified',country='United States shown in currency selector; delivery destination not independently entered',currency='USD, selected in country/currency control and requested via query',domain_registration='unknown',first_wayback='unknown',oldest_review='unknown',facebook_creation='unknown',oldest_shopify_product='unknown',age_class='unclear: age evidence incomplete',source_urls=prod+' ; '+policy,source_date='2026-11-10',tier='◆ / ◈',note='US/USD locale shown, but delivery address not selected. Clicking One Time Purchase unexpectedly added two items to the empty session cart; removed and confirmed cart empty. No purchase or checkout. Seller claims and customer-panel percentages unverified; observed subscription behavior needs checkout confirmation.')
if not any(r['domain']==row['domain'] and r['category']==row['category'] for r in rows):rows.append({k:row.get(k,'') for k in fields})
with f.open('w',encoding='utf-8-sig',newline='') as stream:
 w=csv.DictWriter(stream,fieldnames=fields);w.writeheader();w.writerows(rows)
with (p/'METHOD_LOG.md').open('a',encoding='utf-8') as stream:stream.write('\n- 2026-11-10: public TrySkult product page '+prod+' and '+policy+' read in built-in browser. One Time Purchase link unexpectedly added two items to empty session cart at $44.99; both removed and empty state verified; no purchase. Product page says cancel anytime whereas policy specifies two-cycle minimum. Browser tab closed.\n')
